  function exportiereZauberJson(){
    if(!adminAktiv()){alert('Der Export der zentralen Zauberdatenbank ist nur im Admin-Modus möglich.');return}
    const basis=basisDaten&&typeof basisDaten==='object'?basisDaten:{};
    const aender=readJson(ADMIN_AENDERUNGEN_KEY,{}),neu=readJson(ADMIN_NEU_KEY,[]);
    // Nur Basiszauber und Admin-Ergänzungen: private Benutzerzauber bleiben privat.
    const result=(basis.zauber||[]).map(z=>aender[z.id]?{...z,...aender[z.id],id:z.id}:z);
    const ids=new Set(result.map(z=>String(z.id)));
    for(const z of neu){if(ids.has(String(z.id)))continue;result.push({...z,standard:true});ids.add(String(z.id))}
    const payload={...basis,anzahl:result.length,zauber:result};
    const blob=new Blob([JSON.stringify(payload,null,2)+'\n'],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='zauber.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }

